*************************************************************************
** This file contains the implementation of the datetimeTruncateFunc()
** function for SQLite, which truncates a timestamp to a specified precision.
*/

#include "sqliteInt.h"
#include "vdbe.h"
#include <string.h>
#include <time.h>

/*
** datetimeTruncateFunc() - Truncate a timestamp to the specified precision.
**
** Arguments:
**   argv[0] - The timestamp (TEXT or INTEGER)
**   argv[1] - The unit to truncate to (TEXT: 'year', 'month', 'day', 'hour', 'minute', 'second')
**
** Returns:
**   TEXT in 'YYYY-MM-DD HH:MM:SS' format, or NULL on error/NULL input
*/
void datetimeTruncateFunc(
  sqlite3_context *context,
  int argc,
  sqlite3_value **argv
){
  sqlite3_int64 epoch;  /* Unix epoch seconds */
  struct tm tm;         /* Broken-down time */
  char zResult[32];     /* Result buffer for ISO string */
  const char *zUnit;    /* Truncation unit */
  int nUnit;            /* Length of unit string */
  int rc;

  /* Validate argument count */
  if( argc!=2 ){
    sqlite3_result_error(context, "datetime_truncate() requires 2 arguments", -1);
    return;
  }

  /* Check for NULL inputs */
  if( sqlite3_value_type(argv[0])==SQLITE_NULL 
   || sqlite3_value_type(argv[1])==SQLITE_NULL ){
    sqlite3_result_null(context);
    return;
  }

  /* Extract unit string */
  zUnit = (const char *)sqlite3_value_text(argv[1]);
  if( zUnit==0 ){
    sqlite3_result_error(context, "Out of memory", -1);
    return;
  }
  nUnit = sqlite3_value_bytes(argv[1]);

  /* Normalize unit to lowercase for comparison */
  for( int i=0; i<nUnit; i++ ){
    char c = zUnit[i];
    if( c>='A' && c<='Z' ) zUnit[i] = c + 32;
  }

  /* Parse timestamp to epoch */
  if( sqlite3_value_type(argv[0])==SQLITE_INTEGER ){
    /* Integer is assumed to be Unix epoch seconds */
    epoch = sqlite3_value_int64(argv[0]);
  }else if( sqlite3_value_type(argv[0])==SQLITE_FLOAT ){
    /* Convert Julian day to epoch */
    double jd = sqlite3_value_double(argv[0]);
    /* Julian day 2440587.5 is Unix epoch 1970-01-01 00:00:00 */
    epoch = (sqlite3_int64)((jd - 2440587.5) * 86400.0);
  }else{
    /* Parse text timestamp */
    const char *zTs = (const char *)sqlite3_value_text(argv[0]);
    if( zTs==0 ){
      sqlite3_result_error(context, "Out of memory", -1);
      return;
    }

    /* Try to parse as Unix epoch first */
    rc = sqlite3Atoi64(zTs, &epoch, 0, SQLITE_UTF8);
    if( rc==0 ){
      /* Successfully parsed as integer */
    }else{
      /* Parse as ISO8601 datetime string */
      /* Format: YYYY-MM-DD HH:MM:SS or similar */
      int year, month, day, hour, minute, second;
      int n;

      /* Try to parse with sscanf */
      n = sscanf(zTs, "%d-%d-%d %d:%d:%d", &year, &month, &day, &hour, &minute, &second);
      if( n<3 ){
        sqlite3_result_error(context, "Unable to parse datetime value", -1);
        return;
      }

      /* Initialize tm structure */
      memset(&tm, 0, sizeof(tm));
      tm.tm_year = year - 1900;
      tm.tm_mon = month - 1;
      tm.tm_mday = day;
      if( n>=4 ) tm.tm_hour = hour;
      if( n>=5 ) tm.tm_min = minute;
      if( n>=6 ) tm.tm_sec = second;

      /* Convert to epoch using timegm (UTC) */
      epoch = timegm(&tm);
      if( epoch<0 ){
        sqlite3_result_error(context, "Datetime out of range", -1);
        return;
      }
    }
  }

  /* Truncate to requested precision */
  if( nUnit==4 && strncmp(zUnit, "year", 4)==0 ){
    /* Truncate to year: set month=1, day=1, hour=0, min=0, sec=0 */
    if( gmtime_r(&epoch, &tm)==0 ){
      sqlite3_result_error(context, "Datetime out of range", -1);
      return;
    }
    tm.tm_mon = 0;   /* January */
    tm.tm_mday = 1;  /* Day 1 */
    tm.tm_hour = 0;
    tm.tm_min = 0;
    tm.tm_sec = 0;
    epoch = timegm(&tm);
  }else if( nUnit==5 && strncmp(zUnit, "month", 5)==0 ){
    /* Truncate to month: set day=1, hour=0, min=0, sec=0 */
    if( gmtime_r(&epoch, &tm)==0 ){
      sqlite3_result_error(context, "Datetime out of range", -1);
      return;
    }
    tm.tm_mday = 1;
    tm.tm_hour = 0;
    tm.tm_min = 0;
    tm.tm_sec = 0;
    epoch = timegm(&tm);
  }else if( nUnit==3 && strncmp(zUnit, "day", 3)==0 ){
    /* Truncate to day: set hour=0, min=0, sec=0 */
    epoch -= (epoch % 86400);
  }else if( nUnit==4 && strncmp(zUnit, "hour", 4)==0 ){
    /* Truncate to hour: set min=0, sec=0 */
    epoch -= (epoch % 3600);
  }else if( nUnit==6 && strncmp(zUnit, "minute", 6)==0 ){
    /* Truncate to minute: set sec=0 */
    epoch -= (epoch % 60);
  }else if( nUnit==6 && strncmp(zUnit, "second", 6)==0 ){
    /* Truncate to second: no-op (epoch is already in seconds) */
  }else{
    sqlite3_result_error(context, "Invalid truncation unit. Use: year, month, day, hour, minute, second", -1);
    return;
  }

  /* Format result back to ISO8601 string */
  if( gmtime_r(&epoch, &tm)==0 ){
    sqlite3_result_error(context, "Datetime out of range", -1);
    return;
  }

  /* Format as 'YYYY-MM-DD HH:MM:SS' */
  sqlite3_snprintf(sizeof(zResult), zResult,
    "%04d-%02d-%02d %02d:%02d:%02d",
    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
    tm.tm_hour, tm.tm_min, tm.tm_sec);

  sqlite3_result_text(context, zResult, -1, SQLITE_TRANSIENT);
}

